// Illustrative copy for layout checks. Photos retain their real Commons credits.
export function entrantBiographyPreview(kind: 'driver' | 'team', id: string, scenario: string | null) {
  const team = kind === 'team';
  const paragraphs = team ? [
    'Демонстрационная история команды для проверки оформления. В этом предпросмотре спортивные показатели вымышлены. Страница объединяет историю коллектива, людей за его результатами и фотографии гоночной техники.',
    'Команда Формулы-1 — это не только два болида на стартовой решётке. За каждым выездом стоят работа конструкторов, подготовка механиков и решения гоночного мостика. История помогает увидеть за сухими результатами людей, которые создают машину и проводят её через весь сезон.',
    'Разные поколения автомобилей показывают, как менялись правила и подход к гонкам. Новые ограничения заставляют искать другие решения в аэродинамике, работе с шинами и компоновке машины. Поэтому фотография прошлых лет дополняет рассказ, а её подпись сохраняет настоящий контекст снимка.',
    'Пилоты и руководители меняются, но накопленный опыт остаётся частью команды. Результаты сезона можно сопоставить с карьерными достижениями выше, а состав выбранного года открыт отдельными ссылками. Демонстрационный текст показывает, как длинная биография читается на телефоне и широком экране.',
  ] : [
    'Демонстрационная биография пилота для проверки оформления. Здесь показано, как рассказ о карьере сочетается с фотографией на трассе, личными сведениями и точными результатами. Показатели этого предпросмотра вымышлены.',
    'Путь в Формулу-1 начинается задолго до первого Гран-при. Работа в младших сериях, знакомство с инженерами и первые тесты постепенно формируют стиль пилота. Полная биография сохраняет эти детали, а не ограничивается несколькими предложениями рядом с портретом.',
    'Гоночный уик-энд раскрывает разные стороны мастерства. В квалификации важен один быстрый круг, в гонке — стабильность на дистанции, работа с шинами и выбор момента для атаки. Статистика помогает сравнить результаты, а текст объясняет контекст карьеры без подмены официальных показателей.',
    'Фотографии возвращают этому рассказу атмосферу настоящей трассы. Подпись указывает автора и источник; снимок прошлых лет не выдаётся за фотографию выбранного сезона. На этой странице проверяется оформление статьи, а полный материал доступен по ссылке на источник.',
  ];
  const image = team && id === 'mclaren' ? {
    url: 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/McLaren_MCL38.jpg/1280px-McLaren_MCL38.jpg',
    source_url: 'https://commons.wikimedia.org/wiki/File:McLaren_MCL38.jpg',
    caption: 'McLaren MCL38 в пит-лейне Гран-при Китая, 2024 год.',
    author: 'Liauzh', license: 'CC BY-SA 4.0', license_url: 'https://creativecommons.org/licenses/by-sa/4.0/', width: 1280, height: 720,
  } : !team && id === 'NOR' ? {
    url: 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/2024_British_GP_qualifying_-_Norris.jpg/1280px-2024_British_GP_qualifying_-_Norris.jpg',
    source_url: 'https://commons.wikimedia.org/wiki/File:2024_British_GP_qualifying_-_Norris.jpg',
    caption: 'Ландо Норрис на квалификации Гран-при Великобритании, 2024 год.',
    author: '5225C', license: 'CC BY-SA 4.0', license_url: 'https://creativecommons.org/licenses/by-sa/4.0/', width: 1280, height: 960,
  } : null;
  return {
    bio: scenario === 'entrant-empty' ? '' : paragraphs.join('\n\n'),
    biography_image: scenario === 'entrant-empty' || scenario === 'entrant-story-no-image' ? null : scenario === 'entrant-story-image-error' && image ? { ...image, url: '/missing-biography-image.jpg' } : image,
  };
}
